-- Approved existing-lead fallback: no invented referral or missing amount confirmation.
UPDATE public.daisy_call_scripts SET
history=coalesce(history,'[]'::jsonb)||jsonb_build_array(jsonb_build_object('version',version,'title',title,'category',category,'direction',direction,'content',content,'saved_at',now())),
content=content||jsonb_build_object('script_text','[PrepHub:amount_no_goal]\nThis is Daisy with the DPA Help Center, following up on your first-time homebuyer request for assistance.\n\n'||(content->>'script_text'),'key_points',(SELECT coalesce(jsonb_agg(point),'[]'::jsonb) FROM jsonb_array_elements_text(content->'key_points') point WHERE point NOT LIKE 'Use the recorded assistance goal when present%')||jsonb_build_array('For a linked client whose form has no positive assistance amount, use amount_no_goal then continue directly into the saved email step in the same turn. Never say Doug told me to call to an existing form lead. Do not invent or ask to confirm a missing amount. Keep the unlinked-number introduction only for a call without a client profile.')),
version=version+1,updated_at=now() WHERE script_number=40 AND version=28 AND deleted_at IS NULL;
